 <div class="overlay clear hidden" id="intro"><div class="card panel"><span class="eyebrow" id="intro-no">스테이지 1</span><h2 id="intro-name"></h2><canvas class="intro-ball" id="intro-ball" width="16" height="16"></canvas><p id="intro-text"></p><button class="btn primary" id="intro-go" data-fs-resume>시작</button><p class="fate-note" id="intro-fate"></p><div id="test-balls" hidden></div><button class="btn reroll" id="intro-reroll">다시 뽑기</button></div></div>
